<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\SmtpOutboundConfigRef;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Service\Visibility\SmtpOutboundConfigVisibilityService;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\Gateway\SmtpOutboundConfigWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SmtpOutboundConfigUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SmtpOutboundConfigVisibilityService $visibility,
        private readonly SmtpOutboundConfigWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?SmtpOutboundConfigRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for Smtp outbound config");
        $span = $this->startSpan("Check allow update usecase for Smtp outbound config");
        try {
            $result = $this->dispatcher->dispatch(new SmtpOutboundConfigUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?SmtpOutboundConfigRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for Smtp outbound config");
        $span = $this->startSpan("Check fixed fields for update usecase for Smtp outbound config");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, SmtpOutboundConfigUpdateParams $params): SmtpOutboundConfigUpdateResult
    {
        $this->logDebug("Run update usecase for Smtp outbound config");
        $span = $this->startSpan("Run update usecase for Smtp outbound config");
        try {
            $ref = new SmtpOutboundConfigRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update Smtp outbound config');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new SmtpOutboundConfigUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new SmtpOutboundConfigUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new SmtpOutboundConfigUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
